with metrics as (select id, plan, monthly_fee, status, percent_rank() over w_ordered as monthly_fee_percent_rank, avg(monthly_fee) over (partition by customer_id) as customer_id_avg_monthly_fee, avg(monthly_fee) over (order by end_date, id rows between 6 preceding and current row) as monthly_fee_avg_6 from subscriptions window w_ordered as (partition by plan order by monthly_fee)) select case when monthly_fee >= 213 then 'PREMIUM' else 'STANDARD' end as monthly_fee_tier, case when monthly_fee_percent_rank >= 0.78 then 'HIGH' else 'LOW' end as monthly_fee_percent_rank_tier, avg(monthly_fee_percent_rank) filter (where plan = 'basic') as basic_avg_monthly_fee_percent_rank, size(collect_set(status)) as num_status, sort_array(collect_set(status)) as status_list, size(collect_set(status)) as num_status_2 from metrics group by grouping sets ((case when monthly_fee >= 213 then 'PREMIUM' else 'STANDARD' end, case when monthly_fee_percent_rank >= 0.78 then 'HIGH' else 'LOW' end), (case when monthly_fee >= 213 then 'PREMIUM' else 'STANDARD' end)) order by monthly_fee_percent_rank_tier nulls first;
